//! Deterministic offline rules. Recommendations never imply user selection.
use crate::{models::*, scanner::{self, GOOGLE_HOME, PATCHWALL, PATCHWALL_LEGACY, LAUNCHER, ORIGINAL_LAUNCHER}};
use crate::launcher_variant::{SWIFTOS_VARIANT,SWIFTOS_VERSION_CODE};

pub const DNS_PROVIDERS: [(&str,&str,&str);4] = [
    ("adguard","AdGuard standard","dns.adguard-dns.com"),
    ("pro","HaGeZi Pro","x-hagezi-pro.freedns.controld.com"),
    ("proplus","HaGeZi Pro++","x-hagezi-proplus.freedns.controld.com"),
    ("ultimate","HaGeZi Ultimate","x-hagezi-ultimate.freedns.controld.com"),
];
pub fn dns_hostname(value:&str)->Option<&'static str>{DNS_PROVIDERS.iter().find(|(id,_,host)|*id==value||*host==value).map(|(_,_,host)|*host)}
pub fn capability(snapshot:&DeviceSnapshot,name:&str)->bool{snapshot.inspections.iter().any(|i|i.name==name&&i.status=="detected")}

#[allow(clippy::too_many_arguments)]
fn card(id:&str,area:&str,title:impl Into<String>,description:impl Into<String>,evidence:impl Into<String>,impact:impl Into<String>,restore:impl Into<String>,risk:&str,supported:bool,already_applied:bool,kind:&str,target:&str,value:&str)->Recommendation{
    Recommendation{id:id.into(),area:area.into(),title:title.into(),description:description.into(),evidence:evidence.into(),impact:impact.into(),restore:restore.into(),risk:risk.into(),supported,already_applied,action:ActionRequest{kind:kind.into(),target:target.into(),value:value.into()}}
}

pub fn recommend(snapshot:&DeviceSnapshot)->Vec<Recommendation>{
    let mut result=Vec::new();
    let verified=snapshot.profile.as_deref()==Some(scanner::PROFILE_ID)&&scanner::matches_profile(&snapshot.identity);
    let profile_evidence=if verified {"Validated MiTV-AXSO1 / Android 9 / PI.6157 rule."}else{"Recognized optional package; this model/firmware has not been physically validated. Availability is based on this scan's capability checks."};
    for package in &snapshot.packages {
        let disabled=matches!(package.enabled,Some(2..=4));
        let supported=capability(snapshot,"Package disable")&&!package.protected&&package.enabled.is_some();
        if scanner::allowed_optional(&package.id){
            let is_reporting=["com.miui.tv.analytics","com.google.android.feedback","com.google.android.tv.bugreportsender"].contains(&package.id.as_str());
            let area=if is_reporting {"Privacy"} else {"Apps"};
            let evidence=format!("{profile_evidence} Installed: {}; enabled state: {}. {}",package.installed,package.enabled.map(|v|v.to_string()).unwrap_or_else(||"unreadable".into()),package.reason);
            result.push(card(&format!("disable:{}",package.id),area,format!("Disable {}",package.label),if is_reporting{"Turn off this specific analytics or report-submission service while keeping its APK and data."}else{"Hide and stop an app you do not use while retaining its installation and data."},&evidence,&package.reason,"Restore reinstates the exact recorded enabled state. Changes made before this app have no known original baseline.","low",supported&&package.installed,disabled||!package.installed,"disable",&package.id,""));
            result.push(card(&format!("uninstall:{}",package.id),"Apps",format!("Uninstall {} for this TV user",package.label),"Remove this app from the current user's app list. The factory system copy is retained; this does not erase its read-only system APK.",&evidence,&package.reason,"The retained factory copy can be restored for this user. Downloaded updates and private sign-in state cannot be promised after uninstalling.","medium",verified&&capability(snapshot,"Package uninstall")&&supported&&package.system&&package.installed,!package.installed,"uninstall",&package.id,""));
            if !package.installed||disabled {result.push(card(&format!("enable:{}",package.id),"Apps",format!("Bring back {}",package.label),"Reinstall the retained factory app for this user if needed, then enable it.",&evidence,"The app and its background services become available again.","This is a new recorded choice. For an exact undo of one of this app's changes, use Restore Centre.","low",supported,false,"enable",&package.id,""));}
        }
        if [GOOGLE_HOME,PATCHWALL,PATCHWALL_LEGACY].contains(&package.id.as_str()){
            let is_patchwall=[PATCHWALL,PATCHWALL_LEGACY].contains(&package.id.as_str());
            let impact=if is_patchwall {"The Mi button may stop opening PatchWall. Keep PatchWall if you want that button to work."}else{"Google's Home screen and featured recommendations become unavailable while it is disabled."};
            result.push(card(&format!("disable:{}",package.id),"Launchers",format!("Disable {}",package.label),"Choose each original Home screen separately. A working replacement Home must be confirmed before this operation can finish.",format!("{profile_evidence} Installed: {}; state: {:?}. Preferred Home: {}.",package.installed,package.enabled,snapshot.home_component.as_deref().unwrap_or("unknown")),impact,"Restore returns this package's exact enabled state. Making it preferred Home is a separate action.","medium",supported&&package.installed,disabled||!package.installed,"disable",&package.id,""));
            if disabled||!package.installed{result.push(card(&format!("enable:{}",package.id),"Launchers",format!("Enable {}",package.label),"Keep this original launcher available alongside the replacement Home.",format!("Current enabled state: {:?}; installed: {}.",package.enabled,package.installed),if is_patchwall{"Restores access to PatchWall and may restore the Mi button's destination."}else{"Makes Google Home available again. Xiaomi's firmware may prioritize it over another preferred Home."},"This does not automatically choose preferred Home. A supported Home can be chosen separately.","medium",supported,false,"enable",&package.id,""));}
            let observed=snapshot.inspections.iter().filter(|i|i.name=="Home activities"&&i.status=="detected").flat_map(|i|i.detail.lines()).find(|c|c.split_once('/').map(|(p,_)|p==package.id).unwrap_or(false));
            let component=observed.or_else(||if verified&&package.id==GOOGLE_HOME{Some("com.google.android.tvlauncher/.MainActivity")}else{None});
            if let Some(component)=component { result.push(card(&format!("home:{}",package.id),"Launchers",format!("Make {} my Home screen",package.label),"Use this original launcher when you press Circle/Home.",format!("Preferred Home: {}",snapshot.home_component.as_deref().unwrap_or("unknown")),"The app must be installed and enabled. The recovery timer restores the previous Home if you do not confirm.","Previous preferred Home is recorded independently of app-enabled state.","medium",capability(snapshot,"Home switch")&&capability(snapshot,"Detached recovery")&&supported&&package.installed&&!disabled,snapshot.home_component.as_deref()==Some(component),"set_home",component,"")); }
        }
        // Ordinary downloaded apps are user choices, with complete APK backup required by uninstall.
        if !package.system&&!package.protected&&!package.is_launcher&&package.installed&&package.enabled.is_some(){
            let kind=if disabled{"enable"}else{"disable"};
            result.push(card(&format!("{kind}:{}",package.id),"User apps",format!("{} {}",if disabled{"Bring back"}else{"Disable"},package.label),"Keep an app you use, or turn it off without removing its installation.","Downloaded app with a readable per-user enabled state.","This app's playback, downloads and notifications are unavailable while disabled.","Restore returns the exact saved enabled state.","medium",capability(snapshot,"Package disable"),false,kind,&package.id,""));
            result.push(card(&format!("uninstall:{}",package.id),"User apps",format!("Uninstall {}",package.label),"Remove this downloaded app for the selected TV user. All installed APK splits must be backed up and verified first.","Downloaded app; system services and launchers are excluded.","Private app data, downloads and sign-ins may not survive removal or reinstallation.","Reinstalls the verified APK backup where Android permits it. Private data is not guaranteed.","medium",capability(snapshot,"Package uninstall"),false,"uninstall",&package.id,""));
        }
        // Closing a user app is transient. Never recommend force-stopping system services or a launcher.
        if !package.system&&!package.protected&&!package.is_launcher&&package.installed&&matches!(package.enabled,Some(0|1)){
            result.push(card(&format!("close:{}",package.id),"Memory",format!("Close {} temporarily",package.label),"Close this selected app's current process. Prefer leaving Android to manage memory unless an app is stuck.","Downloaded user app; no guaranteed RAM saving or speed gain.","Playback, downloads and notifications from this app can stop until it is opened again.","Open the app again. Closing an app is temporary and has no exact process-state Undo.","medium",true,false,"force_stop",&package.id,""));
        }
    }

    for (id,label,variant) in [(LAUNCHER,"SwiftOS","custom"),(ORIGINAL_LAUNCHER,"CleanYourTV original Home","original")]{
        let package=snapshot.packages.iter().find(|p|p.id==id);
        let current=package.filter(|p|p.installed);
        let current_version=current.map(|p|p.version_code).unwrap_or(0);
        let exact_custom=id==LAUNCHER&&current_version==SWIFTOS_VERSION_CODE;
        let description=if id==LAUNCHER{format!("Install the signed SwiftOS {} with the selected Home appearance. Existing preferences survive a compatible update. Native remote keys stay with Android; Kolkata weather is optional and starts off on other TV models.",SWIFTOS_VARIANT)}else{"Install the separately packaged original CleanYourTV Home. Your custom SwiftOS Home remains available.".to_string()};
        let validation=if verified{format!("A supported compatibility profile matched. {} requires its own physical remote check.",SWIFTOS_VARIANT)}else{"This model has not been physically validated; remote and startup behavior require checks.".to_string()};
        result.push(card(&format!("install:{id}"),"Launchers",format!("{} {label}",if current.is_some(){"Update"}else{"Install"}),description,format!("Android API {}; requires API 26+. Detected version code: {current_version}. {validation}",snapshot.identity.api),"Installing does not select a default Home or disable either original launcher. No private signing key is distributed. A newer custom version cannot be downgraded by this package.","A newly installed app can be removed. Updating cannot automatically restore an older APK or export all private launcher preferences.","medium",id==LAUNCHER&&verified&&capability(snapshot,"Home switch")&&snapshot.identity.api>=26&&current_version<=SWIFTOS_VERSION_CODE&&(current.is_none()||current_version>=20),exact_custom,"install_launcher",id,variant));
        let observed=snapshot.inspections.iter().filter(|i|i.name=="Home activities"&&i.status=="detected").flat_map(|i|i.detail.lines()).find(|c|c.split_once('/').map(|(p,_)|p==id).unwrap_or(false));
        let component=observed.map(str::to_string).unwrap_or_else(||if id==ORIGINAL_LAUNCHER{format!("{id}/com.gathin.tvhome.MainActivity")}else{format!("{id}/.MainActivity")});
        result.push(card(&format!("home:{id}"),"Launchers",format!("Make {label} my Home screen"),"Start a 150-second recovery timer, open Home, then confirm that Home and the remote work.",format!("Installed: {}. Preferred Home: {}.",current.is_some(),snapshot.home_component.as_deref().unwrap_or("unknown")),"Xiaomi may require its high-priority Google Home to be disabled during a guarded takeover. Choose Replace Google Home explicitly to permit that step.","The timer restores recorded Home/startup/app states without a PC connection. It does not survive TV power loss.","medium",current.map(|p|matches!(p.enabled,Some(0|1))).unwrap_or(false)&&capability(snapshot,"Home switch")&&capability(snapshot,"Detached recovery"),snapshot.home_component.as_deref()==Some(component.as_str()),"set_home",&component,""));
    }
    let installed_custom=snapshot.packages.iter().find(|p|p.id==LAUNCHER&&p.installed);
    let custom_version=installed_custom.map(|p|p.version_code).unwrap_or(0);
    result.push(card("install:swiftos-build22","Launchers","Install SwiftOS 2.7 · build 22","The unchanged earlier Liquid Glass release is kept in this package alongside SwiftOS v3.",format!("Detected installed version code: {custom_version}. Tested Mi TV profile required."),"Both SwiftOS versions use the same app identity. You choose one installed version. Android downgrades are blocked; the tool never uninstalls SwiftOS to force an older version.","Compatible updates preserve preferences. A downgrade or full private-data recovery is not promised.","medium",verified&&snapshot.identity.api>=26&&custom_version<=22,custom_version==22,"install_launcher",LAUNCHER,"build22"));
    if let Some(Some(current))=snapshot.settings.get("swiftos/auto_wallpaper"){for(value,title)in[("1","Enable local Auto wallpaper"),("0","Turn off local Auto wallpaper")]{result.push(card(&format!("wallpaper:{value}"),"Wallpaper",title,"Use the TV's local photos matched to weather and time. Existing forecast data is reused; no background wallpaper service runs.","SwiftOS v3 local-photo protocol detected.","Uploaded photos remain in shared TV storage. Weather uses the existing configured location; offline or stale readings use the Unknown/Any-weather fallback.","Restore returns the exact recorded Auto wallpaper enabled setting. Photo files are kept.","low",verified&&snapshot.identity.user_id==0&&(value=="0"||capability(snapshot,"Local wallpaper photo access")),current==value,"wallpaper_auto","swiftos/auto_wallpaper",value));}}
    let startup=snapshot.settings.get("global/set_patchwall_default");
    result.push(card("patchwall-startup","Launchers","Start with my chosen Home","Turn off Xiaomi's PatchWall-at-startup override without disabling PatchWall.",format!("{profile_evidence} Current startup override: {}.",startup.and_then(|v|v.as_deref()).unwrap_or("absent or unreadable")),"Mi can still open PatchWall if it remains enabled. Reboot/startup should be checked physically.","Restore the exact original value, including a previously absent setting.","low",verified&&startup.is_some(),startup.and_then(|v|v.as_deref())==Some("0"),"patchwall_startup","global/set_patchwall_default","0"));

    let animation_keys=["global/window_animation_scale","global/transition_animation_scale","global/animator_duration_scale"];
    let animations_readable=animation_keys.iter().all(|k|snapshot.settings.contains_key(*k));
    for (value,label,description) in [("0.5","Quicker animations","Reduce standard Android transition time to half speed."),("0","Turn off system animations","Remove standard Android window, transition and animator effects."),("1","Normal system animations","Use normal Android animation speed. Restore Centre can recover earlier custom values.")]{
        let already=animation_keys.iter().all(|k|snapshot.settings.get(*k).and_then(|v|v.as_ref()).and_then(|v|v.parse::<f32>().ok()).map(|v|(v-value.parse::<f32>().unwrap()).abs()<0.001).unwrap_or(false));
        result.push(card(&format!("animations:{value}"),"Animations",label,description,format!("Current scales: {}",animation_keys.iter().map(|k|snapshot.settings.get(*k).map(|v|v.as_deref().unwrap_or("absent")).unwrap_or("unreadable")).collect::<Vec<_>>().join(" / ")),"App-specific and launcher motion can have separate controls. This changes perceived transition time, not processor speed.","Restore all three exact previous values, including settings that were originally absent.","low",animations_readable&&snapshot.identity.api>=17&&capability(snapshot,"Animations capability"),already,"animations","all",value));
    }
    let dns_readable=snapshot.settings.contains_key("global/private_dns_mode")&&snapshot.settings.contains_key("global/private_dns_specifier");
    for (value,label,hostname) in DNS_PROVIDERS {
        let aggressive=["proplus","ultimate"].contains(&value);
        let impact=if aggressive{"Stricter filtering can break app sign-in, video content or streaming. These public DNS providers have no per-TV allowlist. DNS cannot block ads served from the same domains as content."}else{"Some services can fail to load. DNS cannot remove every sponsored section or in-stream ad, including many YouTube ads."};
        let already=snapshot.settings.get("global/private_dns_mode").and_then(|v|v.as_deref())==Some("hostname")&&snapshot.settings.get("global/private_dns_specifier").and_then(|v|v.as_deref())==Some(hostname);
        result.push(card(&format!("dns:{value}"),"Ads & DNS",format!("Use {label} filtering"),"Filter known advertising and tracking domains using encrypted Android Private DNS. Connectivity is verified before keeping the change.",format!("Android API {}. Provider: {hostname}. Previous provider: {}.",snapshot.identity.api,snapshot.settings.get("global/private_dns_specifier").and_then(|v|v.as_deref()).unwrap_or("system default or unreadable")),impact,"Restore the exact previous DNS mode and hostname. Failed connectivity checks trigger rollback.",if value=="ultimate"{"high"}else if aggressive{"medium"}else{"low"},dns_readable&&snapshot.identity.api>=28&&capability(snapshot,"Private DNS"),already,"dns","private_dns",value));
    }
    result.push(card("cache:trim","Storage","Free rebuildable app cache","Ask Android to trim shared rebuildable cache toward 256 MB free storage. Android decides what cache it can safely reclaim.",snapshot.storage_free_kb.map(|v|format!("Free data storage: {:.0} MB.",v as f64/1024.0)).unwrap_or_else(||"Free storage could not be inspected.".into()),"Images or app resources may reload after cleanup. No app data, sign-ins or media are deliberately erased. Freed space is not guaranteed.","No Undo: cached files rebuild as apps need them.","medium",verified&&snapshot.storage_free_kb.is_some(),false,"trim_cache","all","256M"));
    if !capability(snapshot,"Stable TV identity")||!capability(snapshot,"Android TV platform") {for recommendation in &mut result{recommendation.supported=false;recommendation.evidence.push_str(" TV platform or stable identity could not be verified. Applying changes is blocked.");}}
    result
}

#[cfg(test)]mod tests{use super::*;use std::collections::BTreeMap;
 #[test]fn local_wallpaper_enable_requires_photo_access_but_disable_remains_available(){let mut s=snapshot();s.settings.insert("swiftos/auto_wallpaper".into(),Some("0".into()));let r=recommend(&s);assert!(!r.iter().find(|r|r.id=="wallpaper:1").unwrap().supported);assert!(r.iter().find(|r|r.id=="wallpaper:0").unwrap().supported);s.inspections.push(Inspection{name:"Local wallpaper photo access".into(),status:"detected".into(),detail:String::new()});assert!(recommend(&s).iter().find(|r|r.id=="wallpaper:1").unwrap().supported);}
 #[test]fn original_home_uses_observed_activity_namespace(){let mut s=snapshot();s.packages.push(pkg(ORIGINAL_LAUNCHER,Some(0)));s.inspections.push(Inspection{name:"Home activities".into(),status:"detected".into(),detail:"com.gathin.tvhome.original/com.gathin.tvhome.MainActivity".into()});let recs=recommend(&s);assert_eq!(recs.iter().find(|r|r.id==format!("home:{ORIGINAL_LAUNCHER}")).unwrap().action.target,"com.gathin.tvhome.original/com.gathin.tvhome.MainActivity");}
 fn snapshot()->DeviceSnapshot{DeviceSnapshot{identity:DeviceIdentity{serial:"test".into(),device_key:"key".into(),model:"MiTV-AXSO1".into(),manufacturer:"Xiaomi".into(),android_version:"9".into(),api:28,abi:"armeabi-v7a".into(),fingerprint:"test | display=PI.6157 release-keys".into(),user_id:0},scanned_at:0,profile:Some(scanner::PROFILE_ID.into()),packages:vec![],home_component:None,settings:BTreeMap::new(),memory_total_kb:None,memory_available_kb:None,storage_free_kb:None,processes:String::new(),inspections:["Android TV platform","Stable TV identity","Package disable","Package uninstall","Home switch","Detached recovery"].into_iter().map(|name|Inspection{name:name.into(),status:"detected".into(),detail:"test capability".into()}).collect()}}
 fn pkg(id:&str,enabled:Option<u32>)->PackageInfo{PackageInfo{id:id.into(),label:id.into(),installed:true,enabled,system:true,version_name:String::new(),version_code:0,apk_paths:vec![],is_launcher:false,protected:false,reason:String::new(),purpose:scanner::package_purpose(id).into()}}
 #[test]fn permission_failure_cannot_become_actionable(){let mut s=snapshot();s.packages.push(pkg("com.miui.tv.analytics",None));let r=recommend(&s);assert!(!r.iter().find(|r|r.id=="disable:com.miui.tv.analytics").unwrap().supported);assert!(!r.iter().find(|r|r.id=="animations:0.5").unwrap().supported);assert!(!r.iter().find(|r|r.id=="dns:pro").unwrap().supported);}
 #[test]fn recognized_privacy_toggle_is_generic_but_uninstall_is_profiled(){let mut s=snapshot();s.identity.fingerprint="different".into();s.packages.push(pkg("com.miui.tv.analytics",Some(0)));let r=recommend(&s);assert!(r.iter().find(|r|r.id=="disable:com.miui.tv.analytics").unwrap().supported);assert!(!r.iter().find(|r|r.id=="uninstall:com.miui.tv.analytics").unwrap().supported);}
 #[test]fn multiple_original_launchers_are_independent(){let mut s=snapshot();s.packages=vec![pkg(GOOGLE_HOME,Some(3)),pkg(PATCHWALL,Some(0))];let r=recommend(&s);assert!(r.iter().find(|r|r.id==format!("disable:{GOOGLE_HOME}")).unwrap().already_applied);assert!(!r.iter().find(|r|r.id==format!("disable:{PATCHWALL}")).unwrap().already_applied);}
 #[test]fn exact_dns_provider_and_mode_required(){let mut s=snapshot();s.settings.insert("global/private_dns_mode".into(),Some("off".into()));s.settings.insert("global/private_dns_specifier".into(),Some("x-hagezi-pro.freedns.controld.com".into()));assert!(!recommend(&s).iter().find(|r|r.id=="dns:pro").unwrap().already_applied);}
 #[test]fn dns_endpoints_and_stricter_warning(){assert_eq!(dns_hostname("proplus"),Some("x-hagezi-proplus.freedns.controld.com"));assert_eq!(dns_hostname("evil.invalid"),None);let r=recommend(&snapshot());let ultimate=r.iter().find(|r|r.id=="dns:ultimate").unwrap();assert_eq!(ultimate.risk,"high");assert!(ultimate.impact.contains("sign-in"));}
 #[test]fn unknown_packages_are_not_removal_recommendations(){let mut s=snapshot();s.packages.push(pkg("com.vendor.unknown",Some(0)));assert!(!recommend(&s).iter().any(|r|r.action.target=="com.vendor.unknown"));}
 #[test]fn unstable_identity_disables_every_mutation(){let mut s=snapshot();s.inspections.retain(|i|i.name!="Stable TV identity");s.packages.push(pkg("com.miui.tv.analytics",Some(0)));assert!(recommend(&s).iter().all(|r|!r.supported));}
 #[test]fn patchwall_without_home_intent_has_no_preferred_home_card(){let mut s=snapshot();s.packages.push(pkg(PATCHWALL,Some(0)));assert!(!recommend(&s).iter().any(|r|r.id==format!("home:{PATCHWALL}")));assert!(recommend(&s).iter().any(|r|r.id==format!("disable:{PATCHWALL}")));}
}
